  `video` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `policy` text COLLATE utf8mb4_unicode_ci,
  `star_rate` smallint DEFAULT NULL,
  `price` decimal(12,2) DEFAULT NULL,
