  `related_ids` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_user` bigint DEFAULT NULL,
  `update_user` bigint DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `review_score` decimal(2,1) DEFAULT NULL,
  `ical_import_url` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `enable_extra_price` tinyint DEFAULT NULL,
  `extra_price` text COLLATE utf8mb4_unicode_ci,
  `enable_service_fee` tinyint DEFAULT NULL,
  `service_fee` text COLLATE utf8mb4_unicode_ci,
  `surrounding` text COLLATE utf8mb4_unicode_ci,
  `author_id` bigint DEFAULT NULL,
  `min_day_before_booking` int DEFAULT NULL,
  `min_day_stays` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `bravo_hotels_slug_index` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
