INSERT INTO `bravo_locations` VALUES (1,'Paris','New York, a city that doesnt sleep, as Frank Sinatra sang. The Big Apple is one of the largest cities in the United States and one of the most popular in the whole country and the world. Millions of tourists visit it every year attracted by its various iconic symbols and its wide range of leisure and cultural offer. New York is the birth place of new trends and developments in many fields such as art, gastronomy, technology,...','paris',111,'48.856613','2.352222',12,'publish',1,2,NULL,1,NULL,NULL,NULL,NULL,'2025-06-20 16:23:13','2025-06-20 16:23:13',112,'\"[{\\\"title\\\":\\\"Experiencing the best jazz in Harlem, birthplace of bebop\\\",\\\"link\\\":\\\"#\\\",\\\"content\\\":\\\"New Orleans might be the home of jazz, but New York City is where many of the genre\\u2019s greats became stars \\u2013 and Harlem was at the heart of it.The neighborhood experienced a rebirth during the...\\\",\\\"image_id\\\":\\\"113\\\"},{\\\"title\\\":\\\"Reflections from the road: transformative \\u2018Big Trip\\u2019 experiences\\\",\\\"link\\\":\\\"#\\\",\\\"content\\\":\\\"Whether it\\u2019s a gap year after finishing school, a well-earned sabbatical from work or an overseas adventure in celebration of your retirement, a big trip is a rite of passage for every traveller, with myriad life lessons to be ...\\\",\\\"image_id\\\":\\\"114\\\"}]\"',NULL),(2,'New York, United States',NULL,'new-york-united-states',107,'40.712776','-74.005974',12,'publish',3,4,NULL,1,NULL,NULL,NULL,NULL,'2025-06-20 16:23:13','2025-06-20 16:23:13',NULL,NULL,NULL),(3,'California',NULL,'california',108,'36.778259','-119.417931',12,'publish',5,6,NULL,1,NULL,NULL,NULL,NULL,'2025-06-20 16:23:13','2025-06-20 16:23:13',NULL,NULL,NULL),(4,'United States',NULL,'united-states',109,'37.090240','-95.712891',12,'publish',7,8,NULL,1,NULL,NULL,NULL,NULL,'2025-06-20 16:23:13','2025-06-20 16:23:13',NULL,NULL,NULL),(5,'Los Angeles',NULL,'los-angeles',110,'34.052235','-118.243683',12,'publish',9,10,NULL,1,NULL,NULL,NULL,NULL,'2025-06-20 16:23:13','2025-06-20 16:23:13',NULL,NULL,NULL),(6,'New Jersey',NULL,'new-jersey',106,'40.058323','-74.405663',12,'publish',11,12,NULL,1,NULL,NULL,NULL,NULL,'2025-06-20 16:23:13','2025-06-20 16:23:14',NULL,NULL,NULL),(7,'San Francisco',NULL,'san-francisco',107,'37.774929','-122.419418',12,'publish',13,14,NULL,1,NULL,NULL,NULL,NULL,'2025-06-20 16:23:13','2025-06-20 16:23:14',NULL,NULL,NULL),(8,'Virginia',NULL,'virginia',108,'37.431572','-78.656891',12,'publish',15,16,NULL,1,NULL,NULL,NULL,NULL,'2025-06-20 16:23:13','2025-06-20 16:23:14',NULL,NULL,NULL),(9,'London',NULL,'london',107,'37.431572','-78.656891',12,'publish',17,18,NULL,1,NULL,NULL,NULL,NULL,'2025-06-20 16:23:13','2025-06-20 16:23:14',NULL,NULL,NULL),(10,'Germany',NULL,'germany',106,'37.431572','-78.656891',12,'publish',19,20,NULL,1,NULL,NULL,NULL,NULL,'2025-06-20 16:23:13','2025-06-20 16:23:14',NULL,NULL,NULL);
